head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pLIST_PROMT_SEQ = "";
// 세션정보를 얻기위한 함수사용
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd"); // 오늘날짜

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06002.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    const YY = scwin.vCurDate.substr(0, 4);
    const YY_1 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 1;
    const YY_2 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 2;
    const YY_3 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 3;
    const YY_4 = parseInt(scwin.vCurDate.substring(0, 4), 10) - 4;
    edt_SDate.setValue(YY + "0101");
    edt_EDate.setValue(YY + "1231");
    const strCbd_SME_YN = "전체^all," + YY + "^" + YY + "," + YY_1 + "^" + YY_1 + "," + YY_2 + "^" + YY_2 + "," + YY_3 + "^" + YY_3 + "," + YY_4 + "^" + YY_4;
    cmb_PeriodTp.CBData = strCbd_SME_YN;

    // 담당자
    const sbmOptions = {
        id : "sbm_dts_EmpNo",
        action : "/ListPromtHistMgt.do",
        ref : "",
        target : "dts_EmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "^전체";
    if (dts_EmpNo.getRowCount() > 0) {
        for (let i = 1; i <= dts_EmpNo.getRowCount(); i++) {
            strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_EmpNo.getCellData(i, "EMP_NO") + "^" + dts_EmpNo.getCellData(i, "DEP_EMP_NM");
        }
        cmb_EMP_NO.CBData = strCbd; //	담당자

    }
    cmb_EMP_NO.setSelectedIndex(0);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06002.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06002.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06002.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function() {
    try {
        await scwin.excelDown();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06002.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        await scwin.openDetail(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06002.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06002.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06002.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        scwin.setDate(cmb_PeriodTp.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF06002.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_COM_NM_onkeydown
 * @description txb_COM_NM 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_COM_NM_onkeydown = async function() {
    try {
        if (window.event.keyCode === 13) {
            if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
                await scwin.listSync();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06002.txb_COM_NM_onkeydown" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF06002.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 상장유치실적조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "&inputMessageId=LISTPROMTPRFMLIST_INOUT&outputMessageId=LISTPROMTPRFMLIST_INOUT";
    url += "&SDATE=" + edt_SDate.getValue();
    url += "&EDATE=" + edt_EDate.getValue();
    url += "&COMPANY_NM=" + txb_COM_NM.getValue();
    url += "&EMPLOYEE_NO=" + cmb_EMP_NO.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ListPromtHistMgt.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setDate
 * @description 면담일 연도별검색Setting
 * @param {*} pYear pYear
 * @returns {void}
 * @hidden N
 */
scwin.setDate = function(pYear) {
    if (pYear === "all") {
        edt_SDate.setValue("");
        edt_EDate.setValue("");
    } else {
        edt_SDate.setValue(pYear + "0101");
        edt_EDate.setValue(pYear + "1231");
    }
};

/**
 * @method
 * @name excelDown
 * @description 정보를 excel로 다운 받는다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function() {
    if (dts_List.getRowCount() > 0) {
        $c.stf.doLogSave("ULDSTF06002.xml", SCREN_PROCS_TP_CD_01);
        $c.data.downloadGridViewExcel(grd_List, {fileName: "상장유치실적조회", type: "3"});
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name openDetail
 * @description OnDblClick Event 처리
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetail = async function(row) {
    let pageNM;
    scwin.setListPromtSeq(row);
    pageNM = "ULDSTF06001";
    const options = {
        id: "" + pageNM + "",
        title: " 상장유치 실적입력",
        type: "browserPopup",
        width: "1265px",
        height: "755px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/lstmgt/" + pageNM + ".gfm", options);
};

/**
 * @method
 * @name setListPromtSeq
 * @description set List Promt Seq 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setListPromtSeq = function(obj) {
    scwin.pLIST_PROMT_SEQ = dts_List.getCellData(Number(obj), "LIST_PROMT_SEQ");
};

/**
 * @method
 * @name getListPromtSeq
 * @description get List Promt Seq 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListPromtSeq = function() {
    return scwin.pLIST_PROMT_SEQ;
};
